/** Decoder **/

var data = decodeToJson(payload);
var p = data || {};

var hw = p.hw || {};
var ram = hw.ram || {};
var disk = hw.disk || {};
var analysis = p.analysis || {};

function safeNumber(value, fallback) {
    if (value === undefined || value === null || value === "") {
        return fallback;
    }

    var n = Number(value);

    if (isNaN(n)) {
        return fallback;
    }

    return n;
}

function safeString(value, fallback) {
    if (value === undefined || value === null) {
        return fallback;
    }

    return String(value);
}

function boolToNumber(value) {
    return value === true ? 1 : 0;
}

// Calcolo metriche derivate dalla lista spores
var spores = analysis.spores || [];
var germinatedCount = 0;
var avgAreaUm2 = 0;
var avgDiameterUm = 0;
var avgSkeletonLengthUm = 0;
var maxSkeletonLengthUm = 0;

if (spores && spores.length > 0) {
    var areaSum = 0;
    var diameterSum = 0;
    var skeletonSum = 0;

    for (var i = 0; i < spores.length; i++) {
        var s = spores[i] || {};

        if (s.is_germinated === true) {
            germinatedCount += 1;
        }

        var area = safeNumber(s.area_um2, 0);
        var diameter = safeNumber(s.equivalent_diameter_um, 0);
        var skeleton = safeNumber(s.skeleton_length_um, 0);

        areaSum += area;
        diameterSum += diameter;
        skeletonSum += skeleton;

        if (skeleton > maxSkeletonLengthUm) {
            maxSkeletonLengthUm = skeleton;
        }
    }

    avgAreaUm2 = areaSum / spores.length;
    avgDiameterUm = diameterSum / spores.length;
    avgSkeletonLengthUm = skeletonSum / spores.length;
}

return {
    deviceName: safeString(p.device_id, "sensore_001"),
    deviceType: "Optical Biosensor",

    attributes: {
        sample_id: safeString(p.sample_id, ""),
        image_name: safeString(p.image_name, ""),
        image_path: safeString(p.image_path, "")
    },

    telemetry: {
        frame_id: safeNumber(p.frame_id, 0),

        detected: boolToNumber(analysis.detected),
        spore_count: safeNumber(analysis.spore_count, 0),

        growth_stage: safeString(p.growth_stage, ""),
        growth_stage_raw: safeString(p.growth_stage_raw, ""),
        risk_level: safeString(p.risk_level, ""),
        stage_confirmed: boolToNumber(p.stage_confirmed),

        development_index: safeNumber(p.development_index, 0),
        tracked_spore_count: safeNumber(p.tracked_spore_count, 0),
        cumulative_germination_percent: safeNumber(p.cumulative_germination_percent, 0),
        avg_time_to_germination_s: safeNumber(p.avg_time_to_germination_s, 0),
        avg_elongation_rate_um_per_min: safeNumber(p.avg_elongation_rate_um_per_min, 0),

        germinated_count: germinatedCount,
        avg_area_um2: safeNumber(avgAreaUm2, 0),
        avg_equivalent_diameter_um: safeNumber(avgDiameterUm, 0),
        avg_skeleton_length_um: safeNumber(avgSkeletonLengthUm, 0),
        max_skeleton_length_um: safeNumber(maxSkeletonLengthUm, 0),

        cpu_temp_c: safeNumber(hw.cpu_temp_c, 0),
        processing_time_s: safeNumber(hw.processing_time_s, 0),

        ram_used_mb: safeNumber(ram.used_mb, 0),
        ram_total_mb: safeNumber(ram.total_mb, 0),
        ram_used_percent: safeNumber(ram.used_percent, 0),

        disk_used_mb: safeNumber(disk.used_mb, 0),
        disk_free_mb: safeNumber(disk.free_mb, 0),
        disk_used_percent: safeNumber(disk.used_percent, 0)
    }
};
